#include "navcore/road_event.hpp"
#include "navcore/route_monitor.hpp"
#include <fstream>
int main(){navcore::RoadGraph g;for(auto i:{"A","B","C","D"})g.add_node({i,0,0});g.add_edge({"A","B",10,50,1,"x",true});g.add_edge({"B","D",10,50,1,"x",true});g.add_edge({"A","C",15,50,2,"x",true});g.add_edge({"C","D",15,50,2,"x",true});auto o=navcore::route(g,"A","D");navcore::RoadEventOverlay e;auto t=std::chrono::steady_clock::now();e.close("B->D");double apply=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();navcore::MatchResult m{g.outgoing("A")[0]};auto rr=navcore::reroute_if_needed(g,m,o,"D",navcore::RouteState::ON_ROUTE,e);std::ofstream f("reports/v3_reroute_benchmark.csv");f<<"initial_route_latency_ms,event_application_latency_ms,reroute_latency_ms,initial_expanded_nodes,reroute_expanded_nodes,old_cost,new_cost,cost_delta\n"<<o.runtime_ms<<','<<apply<<','<<rr.latency_ms<<','<<o.expanded_nodes<<','<<rr.new_route.expanded_nodes<<','<<o.total_distance_m<<','<<rr.new_route.total_distance_m<<','<<rr.new_route.total_distance_m-o.total_distance_m<<'\n';std::ofstream d("reports/v3_reroute_benchmark.md");d<<"# V3 reroute benchmark\n\nReal deterministic overlay routing measurements.\n";}